import numpy as np
import forward

D = 10
START = -6.0
STOP = 6.0
M = 1200


def f(x):
    return forward.forward(list(x))


def firstdiff(d, at):
    v = np.zeros(D)
    v[d] = 1.0
    h = 1e-7
    x0 = np.zeros(D)
    x0[d] = at
    return (f(list(x0 + h * v)) - f(list(x0 - h * v))) / (2.0 * h)


def findplace(d, lo, hi):
    slo = firstdiff(d, lo)
    for _ in range(100):
        m = 0.5 * (lo + hi)
        sm = firstdiff(d, m)
        if abs(sm - slo) < 1e-6:
            lo, slo = m, sm
        else:
            hi = m
        if hi - lo < 1e-14:
            break
    return 0.5 * (lo + hi)


vals = np.linspace(START, STOP, M)
# obs is a list of (d, place, jump)
obs = []
for d in range(D):
    s = np.array([firstdiff(d, at) for at in vals])
    diff = np.abs(np.diff(s))
    for i in range(M - 1):
        if diff[i] > 1e-5:
            place = findplace(d, vals[i], vals[i + 1])
            jump = firstdiff(d, place + 1e-8) - firstdiff(d, place - 1e-8)
            obs.append((d, place, jump))

# group observations that share the same hidden unit
used = [False] * len(obs)
units = []
for i in range(len(obs)):
    if used[i]:
        continue
    used[i] = True
    group = [i]
    key = obs[i][1] * obs[i][2]
    for j in range(i + 1, len(obs)):
        if used[j]:
            continue
        other = obs[j][1] * obs[j][2]
        if abs(other - key) < 1e-4 * (abs(key) + 1e-12):
            used[j] = True
            group.append(j)
    row = np.zeros(D)
    for k in group:
        row[obs[k][0]] = obs[k][2]
    units.append(row)

A1_hat = np.array(units[:20])
np.save('/app/stolen_A1.npy', A1_hat)
print('found', len(units), 'units, saved', A1_hat.shape)
